package com.hs.jxc.pur;

import static com.hs.jxc.pur.PurchaseImportService.*;
import com.hs.jxc.common.api.*;
import com.hs.jxc.common.context.RequestContext;
import com.hs.jxc.common.idempotency.IdempotencyExecutor;
import com.hs.jxc.attachment.AttachmentService;
import com.hs.jxc.md.api.ProductImageApi;
import java.util.*;
import org.springframework.stereotype.Service;

/** 照片关系同步完成，FEATURE/INDEX旁路任务共用M1执行器。 */
@Service
public class PurchaseImportPhotoService implements PurchaseImportTaskHandler {
    private final PurchaseImportService imports;private final ProductImageApi images;private final PurchaseImportRecognitionClient client;private final IdempotencyExecutor commands;
    public PurchaseImportPhotoService(PurchaseImportService imports,ProductImageApi images,PurchaseImportRecognitionClient client,IdempotencyExecutor commands){this.imports=imports;this.images=images;this.client=client;this.commands=commands;}
    public Set<String> kinds(){return Set.of("IMAGE_PUBLISH","GALLERY_REBUILD");}
    public Map<String,Object> publish(RequestContext ctx,UUID batch,long rowId,Map<String,Object> body,String key){return imports.tx.execute(s->{var a=imports.access(ctx,true);a.require("md:product:edit");a.require("md:product:view");var b=imports.batch(a,batch,true);var row=imports.row(a,batch,rowId);if(!Boolean.TRUE.equals(body.get("confirmOwnership")))throw Inputs.bad("请明确确认所选照片属于本行商品");if(number(row,"version")!=Inputs.version(body))throw Inputs.conflict();if(row.get("matched_product_id")==null||!Set.of("EXISTING","NEW_REQUESTED").contains(row.get("decision")))throw Inputs.bad("请先人工确认真实商品");if(!(body.get("imageIds") instanceof List<?> ids)||ids.isEmpty()||ids.size()>100||new HashSet<>(ids).size()!=ids.size())throw Inputs.bad("请选择不重复的本行原图");
        return commands.execute(ctx,"POST",BASE+"/"+batch+"/rows/"+rowId+"/photos",key,body,Inputs.id(imports.map(b.get("header")).get("bookId")),()->{var taskIds=new ArrayList<String>();for(Object value:ids){long image=Inputs.id(value);var found=imports.jdbc.queryForList("SELECT i.*,r.association_status FROM pur_order_import_row_image r JOIN pur_order_import_image i ON i.country_id=r.country_id AND i.id=r.image_id JOIN pur_order_import_source src ON src.country_id=i.country_id AND src.id=i.source_id WHERE r.country_id=? AND r.row_id=? AND i.id=? AND src.batch_id=?",a.requireCountry(),rowId,image,batch);if(found.size()!=1||!"CONFIRMED".equals(found.getFirst().get("association_status")))throw Inputs.bad("原图归属尚未确认或不属于本行");var source=found.getFirst();var linked=images.link(ctx,number(row,"matched_product_id"),number(source,"attachment_id"));imports.jdbc.update("UPDATE pur_order_import_row_image SET publish_status='READY',product_image_id=?,publish_product_id=?,publish_error=NULL WHERE country_id=? AND row_id=? AND image_id=?",linked.get("imageId"),row.get("matched_product_id"),a.requireCountry(),rowId,image);var input=new LinkedHashMap<String,Object>(linked);input.put("rowId",rowId);input.put("sourceImageId",image);input.put("productId",row.get("matched_product_id"));UUID task=enqueue(ctx,batch,number(source,"source_id"),"IMAGE_PUBLISH",(int)number(row,"version"),source.get("image_sha256").toString(),input);taskIds.add(task.toString());}var out=imports.snapshot(a,batch);out.put("taskIds",taskIds);return out;},result->imports.batch(a,batch,false));
    });}
    private UUID enqueue(RequestContext ctx,UUID batch,long source,String kind,int revision,String hash,Map<String,Object> input){UUID task=UUID.randomUUID();input.put("generation",task.toString().replace("-",""));imports.jdbc.update("INSERT INTO pur_order_import_task(id,country_id,batch_id,source_id,kind,input_revision,input_hash,requested_by,authorization_basis,input_data,phase,result) VALUES(?,?,?,?,?,?,?,?,?::jsonb,?::jsonb,?,?::jsonb)",task,ctx.countryId(),batch,source,kind,revision,hash,ctx.userId(),imports.json.write(Map.of("userId",ctx.userId(),"tokenHash",ctx.tokenHash())),imports.json.write(input),"FEATURE",imports.json.write(Map.of("photoLink",kind.equals("IMAGE_PUBLISH")?"READY":"NOT_APPLICABLE")));return task;}
    public Map<String,Object> rebuild(RequestContext ctx,UUID batch,String key){return imports.tx.execute(s->{var a=imports.access(ctx,true);a.require("md:product:edit");a.require("md:product:view");var b=imports.batch(a,batch,true);var sources=imports.jdbc.queryForList("SELECT id FROM pur_order_import_source WHERE country_id=? AND batch_id=? ORDER BY id LIMIT 1",Long.class,a.requireCountry(),batch);if(sources.isEmpty())throw Inputs.bad("当前批次没有可追溯来源");return commands.execute(ctx,"POST",BASE+"/gallery/rebuild",key,Map.of("batchId",batch.toString()),Inputs.id(imports.map(b.get("header")).get("bookId")),()->Map.of("id",enqueue(ctx,batch,sources.getFirst(),"GALLERY_REBUILD",(int)number(b,"version"),"GALLERY",new LinkedHashMap<>()).toString(),"status","QUEUED"),r->imports.batch(a,batch,false));});}
    public void validate(RequestContext ctx,Map<String,Object> task){imports.tx.execute(s->{var a=imports.access(ctx,true);a.require("md:product:edit");a.require("md:product:view");UUID batch=(UUID)task.get("batch_id");imports.batch(a,batch,false);if("IMAGE_PUBLISH".equals(task.get("kind"))){var input=imports.map(task.get("input_data"));var row=imports.row(a,batch,Inputs.id(input.get("rowId")));if(number(row,"version")!=number(task,"input_revision")||!Objects.equals(Objects.toString(row.get("matched_product_id")),Objects.toString(input.get("productId"))))throw new ApiException(409,"INPUT_CHANGED","原行商品或版本已变化，请重新确认照片发布");if(imports.jdbc.queryForObject("SELECT count(*) FROM pur_order_import_row_image WHERE country_id=? AND row_id=? AND image_id=? AND product_image_id=? AND association_status='CONFIRMED'",Integer.class,a.requireCountry(),row.get("id"),input.get("sourceImageId"),input.get("imageId"))!=1)throw new ApiException(409,"INPUT_CHANGED","照片归属已变化");}return null;});}
    public AttachmentService.Download asset(RequestContext ctx,Map<String,Object> task,long asset){validate(ctx,task);var input=imports.map(task.get("input_data"));if("IMAGE_PUBLISH".equals(task.get("kind"))){if(Inputs.id(input.get("attachmentId"))!=asset)throw ApiException.forbidden();return images.featureContent(ctx,Inputs.id(input.get("featureId")));}
        // INDEX阶段没有待提取资产时，允许范围明确为空。
        var allowed=input.get("featureAssets")==null?List.<Map<String,Object>>of():list(input.get("featureAssets"));var selected=allowed.stream().filter(f->Inputs.id(f.get("attachmentId"))==asset).findFirst();if(selected.isEmpty())throw ApiException.forbidden();return images.featureContent(ctx,Inputs.id(selected.get().get("featureId")));
    }
    private void ensureFeature(PurchaseImportTaskService.Lease lease,PurchaseImportTaskService runtime,long feature){var state=images.feature(lease.actor(),feature);if("READY".equals(state.get("featureStatus")))return;
        try{var result=client.embed(lease.id(),lease.token(),Inputs.id(state.get("attachmentId")),state.get("sha256").toString());imports.tx.execute(s->{var task=runtime.active(lease);validate(lease.actor(),task);images.saveFeature(lease.actor(),feature,result);return null;});}
        catch(RuntimeException error){String message=error instanceof ApiException api?api.getMessage():"照片特征提取失败";try{imports.tx.execute(s->{var task=runtime.active(lease);validate(lease.actor(),task);images.failFeature(lease.actor(),feature,message);return null;});}catch(RuntimeException stateError){error.addSuppressed(stateError);}throw error;}
    }
    public void execute(PurchaseImportTaskService.Lease lease,PurchaseImportTaskService runtime){String generation=lease.input().get("generation").toString(),linkStatus=lease.kind().equals("IMAGE_PUBLISH")?"READY":"NOT_APPLICABLE";
        try{imports.tx.execute(s->{var task=runtime.active(lease);validate(lease.actor(),task);return null;});
            List<Map<String,Object>> features=lease.kind().equals("IMAGE_PUBLISH")?List.of(Map.of("featureId",lease.input().get("featureId"))):images.pendingFeatures(lease.actor());
            if(lease.kind().equals("GALLERY_REBUILD"))imports.tx.execute(s->{var task=runtime.active(lease);validate(lease.actor(),task);var saved=imports.map(task.get("input_data"));saved.put("featureAssets",features);imports.jdbc.update("UPDATE pur_order_import_task SET phase='FEATURE',input_data=?::jsonb WHERE country_id=? AND id=?",imports.json.write(saved),lease.country(),lease.id());return null;});
            for(var feature:features)ensureFeature(lease,runtime,Inputs.id(feature.get("featureId")));
            var input=images.galleryInput(lease.actor());if(((List<?>)input.get("featureIds")).isEmpty()){if(lease.kind().equals("GALLERY_REBUILD")&&((Number)imports.map(input.get("coverage")).get("photos")).longValue()==0){runtime.complete(lease,Map.of("photoLink",linkStatus,"feature","EMPTY","index","EMPTY"));return;}throw new ApiException(409,"GALLERY_NO_READY_FEATURES","正式图库没有可发布的合格特征，请核对本国启用和照片状态");}input.put("generation",generation);
            imports.tx.execute(s->{var task=runtime.active(lease);validate(lease.actor(),task);var saved=imports.map(task.get("input_data"));if(saved.get("indexBasis")!=null&&!Objects.equals(saved.get("indexBasis"),input.get("basisHash")))throw new ApiException(409,"INPUT_CHANGED","图库依据已变化，请重新发起重建");saved.put("indexBasis",input.get("basisHash"));imports.jdbc.update("UPDATE pur_order_import_task SET phase='INDEX',input_data=?::jsonb,result=?::jsonb WHERE country_id=? AND id=?",imports.json.write(saved),imports.json.write(Map.of("photoLink",linkStatus,"feature","READY")),lease.country(),lease.id());return null;});
            images.beginGeneration(lease.actor(),generation,input);var state=images.generationStatus(lease.actor(),generation);Map<String,Object> manifest;if("READY".equals(state.get("status"))){images.indexContent(lease.actor(),generation);manifest=imports.map(state.get("manifest"));}else{var result=client.index(lease.id(),lease.token(),input);manifest=images.publishIndex(lease.actor(),generation,input,result,()->{var task=runtime.active(lease);validate(lease.actor(),task);});}runtime.complete(lease,Map.of("photoLink",linkStatus,"feature","READY","index","READY","manifest",manifest));
        }catch(RuntimeException error){String message=error instanceof ApiException api?api.getMessage():"照片特征或索引执行失败";try{imports.tx.execute(s->{var task=runtime.active(lease);validate(lease.actor(),task);images.failGeneration(lease.actor(),generation,message);return null;});}catch(RuntimeException stateError){error.addSuppressed(stateError);}throw error;}
    }
}
